INSERT INTO `main_task` (`id`, `text`, `type`, `level`, `picture`, `group`, `item_id`, `author_id`, `textWrap`, `context_id`, `stat_attempts`, `stat_points`) VALUES
(3, '', 1, 1, 'task_pics/photo_line.png', 0, NULL, 1, 's', NULL, 0, 0),
(33, 'Посочете коя е правилната формулировка за функциите на микропроцесора:', 1, 1, '', 0, 1, 1, 'w', NULL, 1, 0),
(34, 'Посочете кое е характерното за микропроцесора:', 1, 1, '', 0, 1, 1, 'w', NULL, 0, 0),
(35, 'Дефинирайте основното предназначение на микропроцесора:', 1, 1, '', 0, 1, 1, 'w', NULL, 7, 0),
(36, 'Посочете вярното означение на микропроцесор в техническа документация:', 1, 1, '', 0, 1, 1, 'w', NULL, 6, 12),
(37, 'Посочете верния отговор. Микропроцесорът, като част от хардуера се произвежда във вид на:', 1, 1, '', 0, 1, 1, 'w', NULL, 6, 6),
(38, 'Посочете верния отговор. Пълен набор от инструкции е:', 1, 1, '', 0, 1, 1, 'w', NULL, 8, 0),
(39, 'Дефинирайте понятието процесор:', 1, 1, '', 39, 1, 1, 'w', NULL, 4, 0),
(40, 'Дефинирайте понятието процесор:', 1, 1, '', 39, 1, 1, 'w', NULL, 0, 0),
(41, 'Посочете кой фиксиран формат използва технологията RISC:', 1, 1, '', 0, 1, 1, 'w', NULL, 7, 8),
(42, 'Посочете коя е правилната формулировка на абревиатура CISC:', 1, 1, '', 0, 1, 1, 'w', NULL, 6, 4),
(43, 'Посочете коя е правилната формулировка на абревиатура RISC:', 1, 1, '', 0, 1, 1, 'w', NULL, 11, 12),
(44, 'Посочете правилната формулировка на развитието при процесорите на персоналните компютри:', 1, 1, '', 0, 1, 1, 'w', NULL, 8, 12),
(45, 'Запишете абревиатурата, с която са известни  микропроцесори (микропроцесори със сложен набор от инструкции или микропроцесори със съкратен набор от инструкции)  при които се акцентира върху хардуера:', 5, 2, '', 0, 1, 1, 'w', NULL, 7, 0),
(46, 'Запишете абревиатурата, с която са известни микропроцесори (микропроцесори със сложен набор от инструкции или микропроцесори със съкратен набор от инструкции) при които се акцентира върху софтуера:', 5, 2, '', 0, 1, 1, 'w', NULL, 7, 0),
(47, 'Набор от сложни инструкции за изчисления е характерно за една от основните архитектури за изграждане на микропроцесори. Решете за коя се отнася това твърдение:', 5, 2, '', 0, 1, 1, 'w', NULL, 3, 0),
(48, 'Решете  кои две твърдения се отасят за CISK микропроцесори:', 1, 2, '', 0, 1, 1, 'w', NULL, 8, 8),
(49, 'Сравнeте RISC и CISC микропроцесорите по отношение на броя на инструкциите, необходими за изпълнението на дадена задача и изберете верния отговор:', 1, 2, '', 49, 1, 1, 'w', NULL, 5, 8),
(50, 'Разграничете  RISC и CISC микропроцесорите по отношение на комплексността на инструкциите и изберете верния отговор:', 1, 2, '', 49, 1, 1, 'w', NULL, 0, 0),
(51, 'Групирайте различни етапи в развитието на микропроцесорите по времеви периоди и изберете верния отговор:', 1, 2, '', 0, 1, 1, 'w', NULL, 7, 8),
(52, 'Разграничете  мултиядрените и мултипроцесорни архитектури на микропроцесорите. В задачата има два верни отговора:', 1, 2, '', 0, 1, 1, 'w', NULL, 9, 20),
(53, 'Разграничи  външната и вътрешната памет на микропроцесора:', 1, 2, '', 0, 1, 1, 'w', NULL, 2, 8),
(54, 'Регистрите, като високоскоростна памет, са част от основен компонент на компютърната система. Посочете кой е той:', 1, 1, '', 0, 2, 1, 'w', NULL, 3, 0),
(55, 'За временно съхранение на данни и инструкции, микропроцесорът използва специални клетки памет. Посочете вярното им название:', 1, 1, '', 0, 2, 1, 'w', NULL, 10, 8),
(56, 'ROM/ Read Only Memory/ като основна част от компютърната система се дефинира като:', 1, 1, '', 0, 2, 1, 'w', NULL, 3, 0),
(57, 'Посочете каква е функционалността, реализираща CISC технологията:', 1, 1, '', 0, 2, 1, 'w', NULL, 4, 4),
(58, 'Посочете как функционира блока за изпълнение на инструкции в CISC микропроцесора:', 1, 1, '', 0, 2, 1, 'w', NULL, 6, 4),
(59, 'Посочете как блокът за вход/изход функционира в CISC микропроцесора:', 1, 1, '', 0, 2, 1, 'w', NULL, 6, 0),
(60, 'Обяснете основните функции на аритметико - логическото устройство:', 1, 2, '', 0, 2, 1, 'w', NULL, 9, 32),
(61, 'Определете  основния функционален блок на CISC микропроцесора, който преобразува инструкциите във вътрешни операции:', 1, 2, '', 0, 2, 1, 'w', NULL, 3, 0),
(62, 'Определете кой функционален блок на CISC микропроцесора обобщава и извлича данните от паметта и ги предоставя на АLU блока за изпълнение на операциите:', 1, 2, '', 0, 2, 1, 'w', NULL, 4, 12),
(63, 'Открийте коя е класическата теория за изграждането на съвременните компютърни системи:', 1, 3, '', 0, 2, 1, 'w', NULL, 6, 12),
(64, 'Определете функционалния блок на CISC микропроцесора, който го свързва с външните устройства:', 1, 3, '', 0, 2, 1, 'w', NULL, 6, 12),
(65, 'Открийте кой функционален блок на CISC микропроцесора модифицира програмното изпълнение в зависимост от условията на процеса:', 1, 3, '', 0, 2, 1, 'w', NULL, 4, 0),
(66, 'Анализирайте третия принцип на Джон Фон Нойман:  \"Програмата и данните се съхраняват в една и съща памет. Различните видове думи се различават по начина, по който се използват, но не и по начина, по който са кодирани\"  и изберете вярно твърдение.', 1, 4, '', 0, 2, 1, 'w', NULL, 2, 0),
(67, 'Определете номерираните  блокове в  обобщена блок-схема на микропроцесор с фон Нойманова (Принстънска) архитектура:', 4, 4, 'task_pics/6.png', 0, 2, 1, 'w', NULL, 8, 10),
(68, 'Определете кой блок на CISC микропроцесора разделя многобайтовите операции на отделни байтове за обработка:', 1, 4, '', 0, 2, 1, 'w', NULL, 5, 0),
(69, 'Определете кой блок на CISC микропроцесора представя графично операциите и преходите между тях:', 1, 4, '', 0, 2, 1, 'w', NULL, 3, 0),
(70, 'Определете кой блок на CISC микропроцесора диференцира операциите в зависимост от размера на операндите:', 1, 4, '', 0, 2, 1, 'w', NULL, 5, 16),
(71, 'Определете кой блок на CISC микропроцесора избира операциите и определя реда на тяхното изпълнение:', 1, 4, '', 0, 2, 1, 'w', NULL, 9, 32),
(72, 'Характеристиката \'тактова честота\' на микропроцесорът се дефинира като:', 1, 1, '', 0, 3, 1, 'w', NULL, 3, 4),
(73, 'Скоростта, с която работи микропроцесорът, определя важен  негов параметър. Посочете кой е той:', 1, 1, '', 0, 3, 1, 'w', NULL, 7, 4),
(74, 'За повишаване скоростта на обмен между микропроцесора и оперативната памет се използва специален вид бързодействаща памет. Посочете как се нарича тя:', 1, 1, '', 0, 3, 1, 'w', NULL, 6, 8),
(75, 'Разгледайте предложената компютърна конфигурация: CPU: Intel Core i5-10400fHexa –Core 3 GHz, 12MB; RAM: 8 GB DDR4 2666 MHz; HDD: 1 TB SATA 7200; nVidia GeForce RTX3060 12GB GDDR6. \n\nВ полето за отговори запишете колко е кеш паметта и съответната мерна единица.', 5, 2, '', 0, 3, 1, 'w', NULL, 7, 0),
(76, 'Решете ширината на коя шина определя колко памет може да адресира микропроцесора. Запишете верния отговор в полето за отговори:', 5, 2, '', 0, 3, 1, 'w', NULL, 5, 0),
(77, 'Разгледайте предложената компютърна конфигурация:\n\nCPU: Intel  Core i5 9400 / 4.1GHz, 9 MB Cashe;\nHDD: 2TB SATA 7200;\nRAM: 16 GB DDR4 2666 MHz; \nnVidia GeForce GT730, DDR3 – 4GB;\n\nВ полето за отговори запишете тактовата честота на микропроцесора и мерната единица:', 5, 2, '', 0, 3, 1, 'w', NULL, 2, 0),
(78, 'Решете в посочения пример към кое поколение принадлежи процесорът Intel Core i3-5200:', 1, 2, '', 0, 3, 1, 'w', NULL, 7, 8),
(79, 'Понякога има неуспешен опит за запис или четене на част от данните в кеша. Решете до какво водят тези пропуски:', 1, 2, '', 0, 3, 1, 'w', NULL, 5, 16),
(80, 'Определете какво представляват инструкциите на микропроцесорите:', 1, 2, '', 0, 3, 1, 'w', NULL, 6, 8),
